  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B029",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made superconducting artificial atoms into a controllable platform for quantum optics and quantum information, opening a new and durable experimental regime.",
        "attribution": "Blais supplied key theoretical foundations; Wallraff and Schoelkopf were central to experimental realization and development. Steven M. Girvin's major theoretical role makes the three-person limit a difficult attribution choice.",
        "maturity": "The platform has been explored and developed for decades, with extensive experimental confirmation and broad international uptake.",
        "uncertainties": [
          "The contribution is collective, and the boundary between foundational theory and experimental realization is difficult to represent within a three-person award."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Juan Ignacio Cirac"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices enabled controlled studies of quantum many-body systems and gave quantum simulation a powerful laboratory realization.",
        "attribution": "Bloch and Greiner represent landmark experimental realizations; Cirac represents influential theoretical foundations. Dalibard and Zoller also made important contributions to the broader field.",
        "maturity": "The methods have produced sustained, reproducible work across laboratories and remain a central tool in many-body physics.",
        "uncertainties": [
          "The discovery is a broad program built through contributions from many groups, so a prize would need a carefully bounded citation."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped-ion quantum computing joined influential proposals for quantum logic with precise experimental control, establishing a leading route to scalable quantum information processing.",
        "attribution": "Cirac and Zoller are central to the theoretical foundations; Blatt represents landmark experimental demonstrations. The broader ion-trap community also contributed substantially.",
        "maturity": "The field has achieved repeated high-fidelity control and multiqubit operations, though large-scale fault-tolerant computation remains unachieved.",
        "uncertainties": [
          "The case is strongest for foundational methods and demonstrations; it is less clear whether the eventual scalable computing regime has matured."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks combine precision measurement with a powerful new standard for time and tests of fundamental physics.",
        "attribution": "Katori and Ye are appropriately recognized for independent, complementary advances in the invention and realization of these clocks.",
        "maturity": "Clock performance and reproducibility have advanced over many years, with the technique established as a major precision-measurement platform.",
        "uncertainties": [
          "The distinction between a major instrument advance and a fundamental discovery may depend on how the scientific impact of clock applications is weighed."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mark Saffman",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade and programmable neutral-atom arrays have opened a flexible route to controlled many-body experiments and quantum computation.",
        "attribution": "Browaeys and Saffman represent important experimental development of neutral-atom arrays; Lukin's work helped establish the underlying physical ideas. Peter Zoller also contributed to the wider theoretical foundation.",
        "maturity": "The platform has made rapid progress and achieved substantial experimental control, but its long-term scientific reach is still developing.",
        "uncertainties": [
          "The most consequential applications and discoveries enabled by large programmable arrays may still lie ahead."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Fedor Jelezko",
        "Jörg Wrachtrup",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Optical control of diamond nitrogen-vacancy spins made individual solid-state defects into accessible quantum systems and useful sensors.",
        "attribution": "Jelezko and Wrachtrup were central to experimental control and characterization; Lukin contributed influential ideas and development of the broader quantum-sensing approach.",
        "maturity": "The system has been repeatedly studied and applied, with strong demonstrations of coherent control and sensing.",
        "uncertainties": [
          "The fundamental physics is compelling, but the distinction between the original enabling discoveries and later sensor applications needs careful definition."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B048",
      "proposed_laureates": [
        "Peter W. Shor",
        "Andrew M. Steane",
        "Alexei Kitaev"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction and fault tolerance established how quantum information can be protected in principle, a profound conceptual advance with deep links to physics.",
        "attribution": "Shor and Steane introduced seminal codes and correction methods; Kitaev developed influential topological approaches. These are distinct contributions within a larger theory.",
        "maturity": "The foundations are exceptionally well established, while full fault-tolerant computation remains an active experimental goal.",
        "uncertainties": [
          "It is unsettled whether the most appropriate recognition point is the foundational theory or later demonstration of sustained fault-tolerant operation."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Andrew N. Cleland",
        "Markus Aspelmeyer",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Cavity optomechanics and quantum acoustics have brought mechanical motion into regimes where quantum control and measurement become possible.",
        "attribution": "Cleland, Aspelmeyer, and Kippenberg represent complementary advances across quantum acoustics and optomechanical control.",
        "maturity": "There are strong demonstrations of quantum control and measurement, but the field is still developing toward a settled, broadly adopted set of landmark results.",
        "uncertainties": [
          "The long-term conceptual impact of these techniques relative to their experimental and technological promise is not yet clear."
        ]
      }
    }
  ]
}
